          code: "# 一个最小的 harness 骨架：模型用固定规则代替，但四个部件都在\nLOG = []\n\n\ndef fake_model(messages):\n    # 真模型在这里是一次网络请求；这里用一条固定规则代替\n    last = messages[-1]['content']\n    if '算' in last:\n        return {'type': 'tool_call', 'name': 'add', 'args': {'a': 17, 'b': 25}}\n    return {'type': 'text', 'text': '任务完成：结果是 42'}\n\n\ndef add(a, b):\n    return str(a + b)\n\n\ndef append(kind, payload):\n    LOG.append({'seq': len(LOG), 'kind': kind, 'payload': payload})\n\n\nmessages = [{'role': 'user', 'content': '帮我算 17 加 25'}]\nappend('user/message', messages[-1])\n\nfor step in range(1, 6):\n    out = fake_model(messages)\n    if out['type'] == 'tool_call':\n        append('assistant/tool-call', out)\n        messages.append({'role': 'assistant', 'content': '调用 add'})\n        result = add(**out['args'])      # 真 harness 会先查权限，再执行\n        append('tool/result', {'name': out['name'], 'text': result})\n        messages.append({'role': 'tool', 'content': result})\n    else:\n        append('assistant/message', out)\n        messages.append({'role': 'assistant', 'content': out['text']})\n        break\n\nprint('日志事件数：', len(LOG))\nprint('消息数组长度：', len(messages))\nfor e in LOG:\n    print(e['seq'], e['kind'])\nprint('最后一条消息：', messages[-1]['content'])\n"
