          code: "# 用纯标准库模拟：消息数组怎么长，超长时怎么裁\ndef rough_tokens(text):\n    # 只是粗略估算：中文一字约一 token，英文四字符约一 token\n    cjk = sum(1 for ch in text if 0x4e00 <= ord(ch) <= 0x9fff)\n    return cjk + (len(text) - cjk) // 4 + 1\n\n\ndef total_tokens(messages):\n    return sum(rough_tokens(m['content']) for m in messages)\n\n\nmessages = [{'role': 'system', 'content': '你是一个简洁的助手，回答不超过三句话。'}]\nturns = [\n    ('user', '帮我把这段话改得礼貌一点：明天之前把表交上来。'),\n    ('assistant', '请你在明天之前把表格提交上来，谢谢。'),\n    ('user', '再短一点。'),\n    ('assistant', '麻烦明天前交表，谢谢。'),\n]\nfor role, text in turns:\n    messages.append({'role': role, 'content': text})\n    print('追加', role, '后：条数 =', len(messages), '，估算 token =', total_tokens(messages))\n\nprint()\nprint('当前完整数组：')\nfor i, m in enumerate(messages):\n    print(i, m['role'], m['content'])\n\nBUDGET = 60\n\n\ndef trim(messages, budget):\n    system = [m for m in messages if m['role'] == 'system']\n    rest = [m for m in messages if m['role'] != 'system']\n    while total_tokens(system + rest) > budget and len(rest) > 2:\n        rest.pop(0)          # 从最早的一条开始丢，但至少留两条\n    return system + rest\n\n\nsmall = trim(messages, BUDGET)\nprint()\nprint('裁剪后条数：', len(small), '，估算 token =', total_tokens(small))\nprint('被丢掉的条数：', len(messages) - len(small), '（从最早的一条开始丢）')\nprint('裁剪后第一条对话：', small[1]['content'])\nprint('注意：原始需求那条已经被丢掉，这就是为什么长会话需要「摘要」而不是一味地删。')\n"
